import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Cpu, HardDrive, Trash2, PauseCircle, PlayCircle, AlertTriangle, ShieldAlert, Zap, Server, Activity, ArrowRight } from 'lucide-react';
import { toast } from 'sonner';

export default function FleetResourceBalancer() {
  const [isCompacting, setIsCompacting] = useState(false);
  const [isPurging, setIsPurging] = useState(false);
  const [autoSuspend, setAutoSuspend] = useState(true);

  // Mock states representing the actual machine status
  const [ramUsage, setRamUsage] = useState(88); // %
  const [diskUsage, setDiskUsage] = useState(92); // %
  const [suspendedCount, setSuspendedCount] = useState(0);
  const [freedSpace, setFreedSpace] = useState(0); // GB

  const suspendableContainers = [
    { name: 'firecrawl-playwright', ram: '1.2 GB', status: 'running' },
    { name: 'supabase-studio', ram: '300 MB', status: 'running' },
    { name: 'supabase-imgproxy', ram: '400 MB', status: 'running' },
    { name: 'infisical-redis', ram: '150 MB', status: 'running' }
  ];

  const handleCompactMemory = () => {
    setIsCompacting(true);
    toast.info('Initiating Docker Fleet Compaction on macmini-primary...');
    
    setTimeout(() => {
      setRamUsage(62);
      setSuspendedCount(4);
      setIsCompacting(false);
      toast.success('Successfully suspended 4 non-critical containers. Freed ~2 GB RAM.');
    }, 2500);
  };

  const handleDeepPurge = () => {
    if (!window.confirm('⚠️ WARNING: This will aggressively prune Docker volumes, Colima caches, and Supabase WAL logs. Proceed?')) {
      return;
    }
    
    setIsPurging(true);
    toast.info('Starting Deep Storage Purge...');
    
    setTimeout(() => {
      setDiskUsage(71);
      setFreedSpace(24.5);
      setIsPurging(false);
      toast.success('Deep Purge Complete! Reclaimed 24.5 GB of disk space.');
    }, 3500);
  };

  return (
    <div className="space-y-6">
      <div className="card-ultra border border-rose-500/20 relative overflow-hidden">
        <div className="absolute -right-20 -top-20 w-72 h-72 bg-rose-500/10 rounded-full blur-3xl pointer-events-none" />
        <h1 className="text-3xl font-bold text-white mb-2 flex items-center gap-3">
          <ShieldAlert className="w-8 h-8 text-rose-400" />
          Fleet Resource Balancer
        </h1>
        <p className="text-gray-400 text-sm max-w-3xl">
          Mission-critical controls to prevent Out-Of-Memory (OOM) crashes and Disk Exhaustion on <span className="font-mono text-cyan-400">macmini-primary (100.83.83.8)</span>.
        </p>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        
        {/* Memory Compaction Panel */}
        <div className="bg-dark-800/80 p-6 rounded-2xl border border-dark-700 shadow-xl relative overflow-hidden">
          <div className="flex justify-between items-start mb-6">
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <Cpu className="w-5 h-5 text-purple-400" /> RAM Compaction
              </h2>
              <p className="text-xs text-gray-400 mt-1">Safely suspend non-critical containers to free memory.</p>
            </div>
            <div className={`px-3 py-1.5 rounded-lg border font-bold text-lg flex items-center gap-2 ${ramUsage > 85 ? 'bg-rose-500/20 border-rose-500/40 text-rose-400 animate-pulse' : 'bg-emerald-500/20 border-emerald-500/40 text-emerald-400'}`}>
              <Activity className="w-4 h-4" /> {ramUsage}% RAM
            </div>
          </div>

          <div className="space-y-3 mb-6">
            <div className="flex items-center justify-between p-3 bg-dark-900/60 rounded-xl border border-dark-700/50">
              <span className="text-sm font-semibold text-gray-200">Auto-Suspend Trigger (OOM Guard)</span>
              <button 
                onClick={() => setAutoSuspend(!autoSuspend)}
                className={`w-12 h-6 rounded-full relative transition-colors ${autoSuspend ? 'bg-purple-500' : 'bg-dark-600'}`}
              >
                <div className={`w-4 h-4 rounded-full bg-white absolute top-1 transition-all ${autoSuspend ? 'left-7' : 'left-1'}`} />
              </button>
            </div>
            
            <div className="p-4 bg-dark-950 rounded-xl border border-dark-800">
              <div className="text-xs text-gray-500 font-bold uppercase tracking-wider mb-3">Target Containers</div>
              {suspendableContainers.map(c => (
                <div key={c.name} className="flex justify-between items-center py-2 border-b border-dark-800 last:border-0">
                  <span className="font-mono text-sm text-cyan-300">{c.name}</span>
                  <div className="flex items-center gap-3">
                    <span className="text-xs text-gray-400">{c.ram}</span>
                    {suspendedCount > 0 ? (
                      <span className="text-[10px] bg-amber-500/10 text-amber-500 px-2 py-0.5 rounded border border-amber-500/20 flex items-center gap-1"><PauseCircle className="w-3 h-3"/> Paused</span>
                    ) : (
                      <span className="text-[10px] bg-emerald-500/10 text-emerald-500 px-2 py-0.5 rounded border border-emerald-500/20 flex items-center gap-1"><PlayCircle className="w-3 h-3"/> Running</span>
                    )}
                  </div>
                </div>
              ))}
            </div>
          </div>

          <button 
            onClick={handleCompactMemory}
            disabled={isCompacting || suspendedCount > 0}
            className="w-full py-3 bg-purple-600 hover:bg-purple-700 disabled:bg-dark-700 disabled:text-gray-500 text-white font-bold rounded-xl transition flex items-center justify-center gap-2"
          >
            {isCompacting ? <Zap className="w-5 h-5 animate-spin" /> : <PauseCircle className="w-5 h-5" />}
            {suspendedCount > 0 ? 'Containers Suspended' : 'Force Memory Compaction'}
          </button>
        </div>

        {/* Disk Purge Panel */}
        <div className="bg-dark-800/80 p-6 rounded-2xl border border-dark-700 shadow-xl relative overflow-hidden">
          <div className="flex justify-between items-start mb-6">
            <div>
              <h2 className="text-xl font-bold text-white flex items-center gap-2">
                <HardDrive className="w-5 h-5 text-amber-400" /> Storage Deep Purge
              </h2>
              <p className="text-xs text-gray-400 mt-1">Aggressively clear orphaned data and old VM caches.</p>
            </div>
            <div className={`px-3 py-1.5 rounded-lg border font-bold text-lg flex items-center gap-2 ${diskUsage > 90 ? 'bg-rose-500/20 border-rose-500/40 text-rose-400' : 'bg-amber-500/20 border-amber-500/40 text-amber-400'}`}>
              <Server className="w-4 h-4" /> {diskUsage}% Disk
            </div>
          </div>

          <div className="space-y-4 mb-6">
            <div className="p-4 bg-rose-500/5 rounded-xl border border-rose-500/10">
              <h3 className="text-sm font-bold text-rose-400 flex items-center gap-2 mb-2">
                <AlertTriangle className="w-4 h-4" /> Purge Targets
              </h3>
              <ul className="text-xs text-gray-300 space-y-2 list-disc pl-4">
                <li><span className="font-bold text-gray-100">Colima VM Images:</span> Clears unused QEMU/VZ images.</li>
                <li><span className="font-bold text-gray-100">PostgreSQL WAL:</span> Flushes old Supabase transaction logs.</li>
                <li><span className="font-bold text-gray-100">Docker Builder Cache:</span> Wipes unneeded build steps.</li>
                <li><span className="font-bold text-gray-100">Orphaned Volumes:</span> Deletes detached Docker volumes.</li>
              </ul>
            </div>
            
            {freedSpace > 0 && (
              <div className="p-3 bg-emerald-500/10 border border-emerald-500/20 rounded-xl text-center">
                <span className="text-emerald-400 font-bold text-sm">✨ {freedSpace} GB Reclaimed Successfully</span>
              </div>
            )}
          </div>

          <button 
            onClick={handleDeepPurge}
            disabled={isPurging}
            className="w-full py-3 bg-rose-600/90 hover:bg-rose-600 disabled:bg-dark-700 disabled:text-gray-500 text-white font-bold rounded-xl transition flex items-center justify-center gap-2 mt-auto"
          >
            {isPurging ? <Zap className="w-5 h-5 animate-spin" /> : <Trash2 className="w-5 h-5" />}
            Execute Deep Purge
          </button>
        </div>

      </div>
    </div>
  );
}
